#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100000
#define MAX_E 600000

static int head[MAX_N + 1];
static int to[MAX_E];
static int next_edge[MAX_E];
static int color[MAX_N + 1];
static int queue[MAX_N];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) head[i] = -1;

    int edge_count = 0;
    for (int i = 1; i <= n; i++) {
        int m;
        scanf("%d", &m);
        while (m--) {
            int x;
            scanf("%d", &x);
            to[edge_count] = x;
            next_edge[edge_count] = head[i];
            head[i] = edge_count++;
        }
    }

    for (int i = 1; i <= n; i++) color[i] = -1;

    for (int start = 1; start <= n; start++) {
        if (color[start] != -1) continue;

        int front = 0, back = 0;
        color[start] = 0;
        queue[back++] = start;

        while (front < back) {
            int u = queue[front++];
            for (int e = head[u]; e != -1; e = next_edge[e]) {
                int v = to[e];
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    queue[back++] = v;
                }
            }
        }
    }

    for (int team = 0; team <= 1; team++) {
        int first = 1;
        for (int i = 1; i <= n; i++) {
            if (color[i] == team) {
                if (!first) putchar(' ');
                printf("%d", i);
                first = 0;
            }
        }
        putchar('\n');
    }

    return 0;
}
